<?php
require_once __DIR__ . '/../../includes/bootstrap.php';$user=require_role('hospital_admin');$s=db()->prepare("SELECT id,name FROM organizations WHERE owner_user_id=? AND approval_status='approved' ORDER BY id DESC LIMIT 1");$s->execute([$user['id']]);$org=$s->fetch();if(!$org)redirect('dashboard.php');$q=db()->prepare("SELECT u.id,u.full_name,u.email,p.patient_code,MAX(a.starts_at) last_visit,COUNT(a.id) visit_count FROM appointments a JOIN users u ON u.id=a.patient_user_id LEFT JOIN patient_profiles p ON p.user_id=u.id WHERE a.organization_id=? GROUP BY u.id,u.full_name,u.email,p.patient_code ORDER BY last_visit DESC");$q->execute([$org['id']]);$patients=$q->fetchAll();$pageTitle='Patient management';require __DIR__.'/../../includes/header.php';?>
<section class="dashboard-welcome"><div><span class="eyebrow">PROVIDER OPERATIONS</span><h1>Patient management</h1><p>Patients who have booked with <?= e($org['name']) ?>. This view is limited to your organization.</p></div><a class="button button-secondary" href="<?= e(url('hospital/dashboard.php')) ?>">← Dashboard</a></section>
<div class="table-card"><?php if(!$patients): ?><div class="empty-state"><h3>No patients yet</h3><p>Patient entries will appear after appointment requests are received.</p></div><?php else: ?><div class="table-scroll"><table><thead><tr><th>Patient ID</th><th>Patient</th><th>Email</th><th>Visits</th><th>Last appointment</th><th>Tickets</th></tr></thead><tbody><?php foreach($patients as $p): ?><tr><td><strong><?= e($p['patient_code'] ?: 'Not assigned') ?></strong></td><td><?= e($p['full_name']) ?></td><td><?= e($p['email']) ?></td><td><?= (int)$p['visit_count'] ?></td><td><?= $p['last_visit']?e(date('M j, Y',strtotime($p['last_visit']))):'—' ?></td><td><a class="text-link" href="<?= e(url('hospital/appointments.php')) ?>">View queue →</a></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></div><?php require __DIR__.'/../../includes/footer.php'; ?>
